using System.ComponentModel.DataAnnotations;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;

namespace FacciStats;
public class Personaje { public int Id { get; set; } public string Nombre { get; set; } = ""; public string Faccion { get; set; } = ""; public bool EstaMuerto { get; set; } public string? BiografiaSecreta { get; set; } public List<Carta> Cartas { get; set; } = []; }
public class Carta { public int Id { get; set; } public int PersonajeId { get; set; } public string Nombre { get; set; } = ""; public int Poder { get; set; } public Personaje? Personaje { get; set; } }
public class Evento { public int Id { get; set; } public string Nombre { get; set; } = ""; public DateTime Fecha { get; set; } public string FaccionGanadora { get; set; } = ""; }
public class Usuario { public int Id { get; set; } public string Nombre { get; set; } = ""; public string Email { get; set; } = ""; public string PasswordHash { get; set; } = ""; public string? Telefono { get; set; } }
public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options) { public DbSet<Personaje> Personajes => Set<Personaje>(); public DbSet<Carta> Cartas => Set<Carta>(); public DbSet<Evento> Eventos => Set<Evento>(); public DbSet<Usuario> Usuarios => Set<Usuario>(); protected override void OnModelCreating(ModelBuilder b) { b.Entity<Personaje>(e => { e.Property(x => x.Nombre).HasMaxLength(100).IsRequired(); e.Property(x => x.Faccion).HasMaxLength(80).IsRequired(); e.Property(x => x.BiografiaSecreta).HasMaxLength(2000); }); b.Entity<Carta>(e => { e.Property(x => x.Nombre).HasMaxLength(100).IsRequired(); e.HasOne(x => x.Personaje).WithMany(x => x.Cartas).HasForeignKey(x => x.PersonajeId).OnDelete(DeleteBehavior.Restrict); }); b.Entity<Evento>(e => { e.Property(x => x.Nombre).HasMaxLength(120).IsRequired(); e.Property(x => x.FaccionGanadora).HasMaxLength(80).IsRequired(); }); b.Entity<Usuario>(e => { e.Property(x => x.Email).HasMaxLength(150).IsRequired(); e.HasIndex(x => x.Email).IsUnique(); e.Property(x => x.PasswordHash).HasMaxLength(255).IsRequired(); e.Property(x => x.Telefono).HasMaxLength(255); }); } }
public class CifradoService { readonly byte[] key; public CifradoService(IConfiguration c) { key = Convert.FromBase64String(c["Cifrado:Clave"] ?? throw new InvalidOperationException("Configura Cifrado:Clave con Secret Manager.")); if (key.Length != 32) throw new InvalidOperationException("La clave AES debe tener 32 bytes en Base64."); } public string Cifrar(string text) { var n = RandomNumberGenerator.GetBytes(12); var plain = Encoding.UTF8.GetBytes(text); var encrypted = new byte[plain.Length]; var tag = new byte[16]; using var aes = new AesGcm(key, 16); aes.Encrypt(n, plain, encrypted, tag); return Convert.ToBase64String(n.Concat(tag).Concat(encrypted).ToArray()); } public string Descifrar(string value) { var all = Convert.FromBase64String(value); var output = new byte[all.Length - 28]; using var aes = new AesGcm(key, 16); aes.Decrypt(all[..12], all[12..28], all[28..], output); return Encoding.UTF8.GetString(output); } }
public record PersonajeRequest([Required, StringLength(100)] string Nombre, [Required, StringLength(80)] string Faccion, bool EstaMuerto, string? BiografiaSecreta);
public record CartaRequest(int PersonajeId, [Required, StringLength(100)] string Nombre, [Range(0, 100000)] int Poder);
public record EventoRequest([Required, StringLength(120)] string Nombre, DateTime Fecha, [Required, StringLength(80)] string FaccionGanadora);
public record UsuarioRequest([Required] string Nombre, [Required, EmailAddress] string Email, [Required, MinLength(8)] string Password, string? Telefono);
public record PersonajeDto(int Id, string Nombre, string Faccion, bool EstaMuerto, string? BiografiaSecreta);
public record FaccionDto(string Faccion, int Personajes, int Vivos, int Muertos, int Cartas, double? PoderPromedio, int EventosGanados, double PorcentajeMuertos);
public class ApiService(AppDbContext db, CifradoService cifrado, IPasswordHasher<Usuario> hasher) { public async Task<PersonajeDto?> Personaje(int id) { var x = await db.Personajes.FindAsync(id); return x is null ? null : Map(x); } public PersonajeDto Map(Personaje x) => new(x.Id,x.Nombre,x.Faccion,x.EstaMuerto,x.BiografiaSecreta is null ? null : cifrado.Descifrar(x.BiografiaSecreta)); public async Task<List<FaccionDto>> Estadisticas() { var ps=await db.Personajes.Include(x=>x.Cartas).AsNoTracking().ToListAsync(); var ev=await db.Eventos.AsNoTracking().ToListAsync(); return ps.GroupBy(x=>x.Faccion.Trim(),StringComparer.OrdinalIgnoreCase).Select(g=>new FaccionDto(g.Key,g.Count(),g.Count(x=>!x.EstaMuerto),g.Count(x=>x.EstaMuerto),g.Sum(x=>x.Cartas.Count),g.SelectMany(x=>x.Cartas).Any()?g.SelectMany(x=>x.Cartas).Average(x=>x.Poder):null,ev.Count(x=>string.Equals(x.FaccionGanadora,g.Key,StringComparison.OrdinalIgnoreCase)),Math.Round(g.Count(x=>x.EstaMuerto)*100.0/g.Count(),2))).OrderBy(x=>x.Faccion).ToList(); } public async Task<Usuario> CrearUsuario(UsuarioRequest r) { var u=new Usuario { Nombre=r.Nombre.Trim(),Email=r.Email.Trim().ToLowerInvariant(),Telefono=string.IsNullOrWhiteSpace(r.Telefono)?null:cifrado.Cifrar(r.Telefono) }; u.PasswordHash=hasher.HashPassword(u,r.Password); db.Usuarios.Add(u); await db.SaveChangesAsync(); return u; } }
